function setup() {
	createCanvas(800, 600);
	background('black');
	// noLoop() removed for animation
}

function draw() {
	noStroke();

	// particles
	for (var p = 0; p < 300; p++) {
		var x = random(width/5, width*4/5);
		var y = random(height/5, height*4/5);
		fill(255, 0, 0, 10);
		ellipse(x, y, 50);

		fill(255, 0, 0, 20);
		for (var i = 0; i < 1000; i++) {
			ellipse(x, y, 2);
			x += 5 * (noise(x/100, y/100, i/100) - 0.5);
			y += 5 * (noise(y/100, i/100, x/100) - 0.5);
		}
	}

	noFill(); stroke(255,0,0); rect(50,50,width-1-100, height-1-100);

}
